import{_ as l,a0 as i,w as p,s,I as a,x as r,a1 as t,A as n,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？ | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？ | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 Linux FAQs with Answers--What is the Apache error log location on Linux","title":"Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？","tag":"201506","desc":""},"relativePath":"201506/20150518 Linux FAQs with Answers--What is the Apache error log location on Linux.md","filePath":"[post].md"}'),h={name:"201506/20150518 Linux FAQs with Answers--What is the Apache error log location on Linux.md"};function d(x,e,m,c,L,g){const o=i("Link");return p(),s("div",null,[e[19]||(e[19]=a("h1",{id:"linux有問必答-linux上apache錯誤日誌的位置在哪裏",tabindex:"-1"},[r("Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？ "),a("a",{class:"header-anchor",href:"#linux有問必答-linux上apache錯誤日誌的位置在哪裏","aria-label":"Permalink to “Linux有問必答：Linux上Apache錯誤日誌的位置在哪裏？”"},"​")],-1)),e[20]||(e[20]=a("blockquote",null,[a("p",null,[a("strong",null,"問題"),r("： 我嘗試着解決我 Linux 系統上的 Apache Web 服務器的錯誤，Apache的錯誤日誌文件放在[XX Linux 版本]的哪個位置呢？")])],-1)),a("p",null,[e[3]||(e[3]=r("錯誤日誌和訪問日誌文件為系統管理員提供了有用的信息，比如，為 Web 服務器排障，",-1)),t(o,{href:"https://linux.cn/article-5068-1.html"},{default:n(()=>[...e[0]||(e[0]=[r("保護",-1)])]),_:1}),e[4]||(e[4]=r("系統不受各種各樣的惡意活動侵犯，或者只是進行",-1)),t(o,{href:"https://linux.cn/article-5352-1.html"},{default:n(()=>[...e[1]||(e[1]=[r("各種各樣的",-1)])]),_:1}),t(o,{href:"https://linux.cn/article-4405-1.html"},{default:n(()=>[...e[2]||(e[2]=[r("分析",-1)])]),_:1}),e[5]||(e[5]=r("以監控 HTTP 服務器。根據你 Web 服務器配置的不同，其錯誤/訪問日誌可能放在你係統中不同位置。",-1))]),e[21]||(e[21]=u(`<p>本文可以幫助你<strong>找到Linux上的Apache錯誤日誌</strong>。</p><p><img src="https://farm8.staticflickr.com/7664/16958522954_4852ab5ea5_c.jpg" alt=""></p><h3 id="debian-ubuntu或linux-mint上的apache錯誤日誌位置" tabindex="-1">Debian，Ubuntu或Linux Mint上的Apache錯誤日誌位置 <a class="header-anchor" href="#debian-ubuntu或linux-mint上的apache錯誤日誌位置" aria-label="Permalink to “Debian，Ubuntu或Linux Mint上的Apache錯誤日誌位置”">​</a></h3><h4 id="默認的錯誤日誌" tabindex="-1">默認的錯誤日誌 <a class="header-anchor" href="#默認的錯誤日誌" aria-label="Permalink to “默認的錯誤日誌”">​</a></h4><p>在基於Debian的Linux上，系統範圍的Apache錯誤日誌默認位置是<strong>/var/log/apache2/error.log</strong>。默認位置可以通過編輯Apache的配置文件進行修改。</p><h4 id="自定義的錯誤日誌" tabindex="-1">自定義的錯誤日誌 <a class="header-anchor" href="#自定義的錯誤日誌" aria-label="Permalink to “自定義的錯誤日誌”">​</a></h4><p>要找到自定義的錯誤日誌位置，請用文本編輯器打開 /etc/apache2/apache2.conf，然後查找以 ErrorLog 開頭的行，該行指定了自定義的 Apache 錯誤日誌文件的位置。例如，在未經修改的 Apache 配置文件中可以找到以下行：</p><pre><code>ErrorLog \${APACHE_LOG_DIR}/error.log
</code></pre><p>在本例中，該位置使用 APACHE_LOG_DIR 環境變量進行配置，該變量在 /etc/apache2/envvars 中已被定義。</p><pre><code>export APACHE_LOG_DIR=/var/log/apache2$SUFFIX
</code></pre><p>在實際情況中， ErrorLog 可能會指向你 Linux 系統中任意路徑。</p><h4 id="使用虛擬主機自定義的錯誤日誌" tabindex="-1">使用虛擬主機自定義的錯誤日誌 <a class="header-anchor" href="#使用虛擬主機自定義的錯誤日誌" aria-label="Permalink to “使用虛擬主機自定義的錯誤日誌”">​</a></h4><p>如果在 Apache Web 服務器中使用了虛擬主機， ErrorLog 指令可能會在虛擬主機容器內指定，在這種情況下，上面所説的系統範圍的錯誤日誌位置將被忽略。</p><p>啓用了虛擬主機後，各個虛擬主機可以定義其自身的自定義錯誤日誌位置。要找出某個特定虛擬主機的錯誤日誌位置，你可以打開 <code>/etc/apache2/sites-enabled/&lt;your-site&gt;.conf</code>，然後查找 ErrorLog 指令，該指令會顯示站點指定的錯誤日誌文件。</p><h3 id="centos-fedora或rhel上的apache錯誤日誌位置" tabindex="-1">CentOS，Fedora或RHEL上的Apache錯誤日誌位置 <a class="header-anchor" href="#centos-fedora或rhel上的apache錯誤日誌位置" aria-label="Permalink to “CentOS，Fedora或RHEL上的Apache錯誤日誌位置”">​</a></h3><h4 id="默認的錯誤日誌-1" tabindex="-1">默認的錯誤日誌 <a class="header-anchor" href="#默認的錯誤日誌-1" aria-label="Permalink to “默認的錯誤日誌”">​</a></h4><p>在基於 Red Hat 的Linux中，系統範圍的 Apache 錯誤日誌文件默認被放置在<strong>/var/log/httpd/error_log</strong>。該默認位置可以通過修改 Apache 配置文件進行自定義。</p><h4 id="自定義的錯誤日誌-1" tabindex="-1">自定義的錯誤日誌 <a class="header-anchor" href="#自定義的錯誤日誌-1" aria-label="Permalink to “自定義的錯誤日誌”">​</a></h4><p>要找出 Apache 錯誤日誌的自定義位置，請用文本編輯器打開 /etc/httpd/conf/httpd.conf，然後查找 ServerRoot，該參數顯示了 Apache Web 服務器目錄樹的頂層，日誌文件和配置都位於該目錄樹中。例如：</p><pre><code>ServerRoot &quot;/etc/httpd&quot;
</code></pre><p>現在，查找 ErrorLog 開頭的行，該行指出了 Apache Web 服務器將錯誤日誌寫到了哪裏去。注意，指定的位置是 ServerRoot 值的相對位置。例如：</p><pre><code>ErrorLog &quot;log/error_log&quot;
</code></pre><p>結合上面的兩個指令，可以獲得完整的錯誤日誌路徑，默認情況下該路徑就是 /etc/httpd/logs/error_log。在全新安裝的Apache中，這是一個到 /var/log/httpd/error_log 的符號鏈接。</p><p>在實際情況中， ErrorLog 可能指向你 Linux 系統中的任意位置。</p><h4 id="使用虛擬主機自定義的錯誤日誌-1" tabindex="-1">使用虛擬主機自定義的錯誤日誌 <a class="header-anchor" href="#使用虛擬主機自定義的錯誤日誌-1" aria-label="Permalink to “使用虛擬主機自定義的錯誤日誌”">​</a></h4><p>如果你啓用了虛擬主機，你可以通過檢查 /etc/httpd/conf/httpd.conf（或其它任何定義了虛擬主機的文件）來找到各個虛擬主機的錯誤日誌位置。在獨立的虛擬主機部分查找 ErrorLog。如，在下面的虛擬主機部分，錯誤日誌的位置是 /var/www/xmodulo.com/logs/error_log。</p><pre><code>&lt;VirtualHost *:80&gt;
    ServerAdmin webmaster@xmodulo.com
    DocumentRoot /var/www/xmodulo.com/public_html
    ServerName www.xmodulo.com
    ServerAlias xmodulo.com
    ErrorLog /var/www/xmodulo.com/logs/error_log
    CustomLog /var/www/xmodulo.com/logs/access_log
&lt;VirtualHost&gt;
</code></pre><hr>`,28)),a("p",null,[e[7]||(e[7]=r("via: ",-1)),t(o,{href:"http://ask.xmodulo.com/apache-error-log-location-linux.html"},{default:n(()=>[...e[6]||(e[6]=[r("http://ask.xmodulo.com/apache-error-log-location-linux.html",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=r("作者：",-1)),t(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:n(()=>[...e[8]||(e[8]=[r("Dan Nanni",-1)])]),_:1}),e[12]||(e[12]=r(" 譯者：",-1)),t(o,{href:"https://github.com/GOLinux"},{default:n(()=>[...e[9]||(e[9]=[r("GOLinux",-1)])]),_:1}),e[13]||(e[13]=r(" 校對：",-1)),t(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[10]||(e[10]=[r("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=r("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[14]||(e[14]=[r("LCTT",-1)])]),_:1}),e[17]||(e[17]=r(" 原創翻譯，",-1)),t(o,{href:"https://linux.cn/"},{default:n(()=>[...e[15]||(e[15]=[r("Linux中國",-1)])]),_:1}),e[18]||(e[18]=r(" 榮譽推出",-1))])])}const w=l(h,[["render",d]]);export{b as __pageData,w as default};
